(()=>{const init=()=>document.querySelectorAll(".auth-referral-offer .rewards").forEach(root=>{if(root.dataset.referralReady)return;root.dataset.referralReady="true";const base=Number(root.dataset.referralBase||100),step=Number(root.dataset.referralStep||25),maximum=Math.min(4,Number(root.dataset.referralMax||4));const cards=[...root.querySelectorAll(".dealer")],pulses=[...root.querySelectorAll(".pulse")],amount=root.querySelector("[data-referral-amount]"),discount=root.querySelector("[data-referral-discount]"),label=root.querySelector("[data-referral-label]"),counter=root.querySelector(".counter");const reduced=matchMedia("(prefers-reduced-motion:reduce)");let started=0,elapsed=0,frame=0,last=-1;function stage(n){cards.forEach((c,i)=>c.classList.toggle("active",i<n));amount.textContent=Number((base*(1-Math.min(100,n*step)/100)).toFixed(2));discount.textContent=Math.min(100,n*step)+"% off";label.textContent="With "+n+" active qualifying referral"+(n===1?"":"s");counter.classList.remove("bump");void counter.offsetWidth;if(n)counter.classList.add("bump")}function tick(t){if(document.hidden||!root.isConnected)return;elapsed=t-started;const n=Math.min(maximum,Math.max(0,Math.floor((elapsed-2450)/1700)));if(n!==last){stage(n);last=n}pulses.forEach((p,i)=>{const start=2450+(i+1)*1700-600;if(elapsed>=start)cards[i].classList.add("active");p.classList.toggle("fire",elapsed>=start&&elapsed<start+650)});if(elapsed<9800)frame=requestAnimationFrame(tick);else root.dataset.referralComplete="true"}function play(){cancelAnimationFrame(frame);pulses.forEach(p=>p.classList.remove("fire"));last=-1;elapsed=0;stage(0);if(reduced.matches){stage(maximum);return}started=performance.now();frame=requestAnimationFrame(tick)}document.addEventListener("visibilitychange",()=>{cancelAnimationFrame(frame);if(hasStarted&&root.isConnected&&!document.hidden&&elapsed<9800&&!reduced.matches){started=performance.now()-elapsed;frame=requestAnimationFrame(tick)}});reduced.addEventListener("change",()=>{if(reduced.matches){cancelAnimationFrame(frame);stage(maximum)}});let hasStarted=false;if(!("IntersectionObserver"in window)){hasStarted=true;play();return}const watcher=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)&&!hasStarted){hasStarted=true;play();watcher.disconnect()}},{threshold:.4});watcher.observe(root)});init();document.addEventListener("guideoffersupdated",init)})();